        var original=await new DeviceAccess().InspectAsync(liveRoot);var host=Path.GetFullPath(output);if(host.StartsWith(Path.GetFullPath(liveRoot),StringComparison.OrdinalIgnoreCase))throw new IOException("镜像必须位于设备之外。");Directory.CreateDirectory(host);var mirror=Path.Combine(host,"mirror-"+Guid.NewGuid().ToString("N")[..8]);var metadata=Path.Combine(mirror,"iPod_Control/iTunes");Directory.CreateDirectory(metadata);File.Copy(Path.Combine(original.Root,original.DatabaseFile),Path.Combine(mirror,original.DatabaseFile));Directory.CreateDirectory(Path.Combine(mirror,"iPod_Control/Device"));await File.WriteAllTextAsync(Path.Combine(mirror,"iPod_Control/Device/SysInfo"),"ModelNumStr: MB751\nSerialNumber: MIRROR-VALIDATION\nFirewireGuid: "+Convert.ToHexString(original.SigningIdentity));
