        var preferences=Path.Combine(liveRoot,"iPod_Control/Device/Preferences");if(File.Exists(preferences))File.Copy(preferences,Path.Combine(mirror,"iPod_Control/Device/Preferences"));var counts=Path.Combine(liveRoot,"iPod_Control/iTunes/Play Counts");if(File.Exists(counts))File.Copy(counts,Path.Combine(mirror,"iPod_Control/iTunes/Play Counts"));
