dentity,covers:new Dictionary<uint,ArtworkLink>{{newTrack,new(image.Id,5000)}});await File.WriteAllBytesAsync(plan.DatabasePath,newDatabase);plan=DeviceSync.Seal(plan with{DatabaseHash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(newDatabase)),Assets=assets});var backup=await sync.CommitAsync(plan);var verified=await new DeviceAccess().InspectAsync(mirror);var manifest=await DeviceBackup.VerifyAsync(backup);var duplicated=await sync.PrepareAsync(verified with{Model=validatedModel},[source with{Id="mirror-source",Path=sourcePath,Hash="",Title="镜像同步验证"}]);var statisticsConsumed=!File.Exists(Path.Combine(mirror,"iPod_Control/iTunes/Play Counts"));var artAfter=new NativeImageDatabase(await File.ReadAllBytesAsync(artPath)).Images().Count;await DeviceFileTransaction.RestoreMetadataAsync(verified with{Model=validatedModel},backup,Path.Combine(host,"host-data"));var restored=await new DeviceAccess().InspectAsync(mirror);var artRestored=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(await File.ReadAllBytesAsync(artPath)))==Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(artOriginal));var liveAfter=await new DeviceAccess().InspectAsync(liveRoot);
